import React, { useState, useEffect } from "react";
import api from "./api/todoList";

const ToDoList = () => {
  const [tasks, setTasks] = useState([]);
  const [task, setTask] = useState("");
  const [editIndex, setEditIndex] = useState(null);

  // Fetch all tasks from JSON Server
  useEffect(() => {
    const getAllTasks = async () => {
      try {
        const response = await api.get("/ToDoList");
        if (response.data) setTasks(response.data);
      } catch (error) {
        console.error("Error fetching tasks:", error);
      }
    };
    getAllTasks();
  }, []);

  // Add Task to API and State
  const addTask = async () => {
    if (task.trim() === "") return;
    const newTask = { id: Date.now().toString(), tasks: task };

    try {
      const response = await api.post("/ToDoList", newTask);
      setTasks([...tasks, response.data]); // API response ka data use karein
      setTask("");
    } catch (error) {
      console.error("Error adding task:", error);
    }
  };

  // Edit Existing Task
  const editTask = (index) => {
    setTask(tasks[index].tasks); // Proper key use karein
    setEditIndex(index);
  };

  // Update Task in API and State
  const updateTask = async () => {
    if (task.trim() === "" || editIndex === null) return;

    const updatedTask = { ...tasks[editIndex], tasks: task };

    try {
      await api.put(`/ToDoList/${tasks[editIndex].id}`, updatedTask);
      const updatedTasks = tasks.map((t, index) =>
        index === editIndex ? updatedTask : t
      );
      setTasks(updatedTasks);
      setTask("");
      setEditIndex(null);
    } catch (error) {
      console.error("Error updating task:", error);
    }
  };

  // Delete Task from API and State
  const deleteTask = async (id) => {
    try {
      await api.delete(`/ToDoList/${id}`);
      setTasks(tasks.filter((task) => task.id !== id));
    } catch (error) {
      console.error("Error deleting task:", error);
    }
  };

  return (
    <div className="max-w-md mx-auto p-4 bg-white shadow-lg rounded-lg">
      <h2 className="text-2xl font-bold text-center mb-4">To-Do List</h2>

      <div className="flex mb-4">
        <input
          type="text"
          placeholder="Enter task..."
          className="flex-1 p-2 border rounded-l"
          value={task}
          onChange={(e) => setTask(e.target.value)}
        />
        <button
          onClick={editIndex !== null ? updateTask : addTask}
          className="bg-blue-500 text-white px-4 py-2 rounded-r hover:bg-blue-600"
        >
          {editIndex !== null ? "Update" : "Add"}
        </button>
      </div>

      <ul>
        {tasks.map((t, index) => (
          <li
            key={t.id} // Use `t.id` instead of `index` for better performance
            className="flex justify-between items-center bg-gray-100 p-2 mt-2 rounded"
          >
            <span>{t.tasks}</span> {/* Use t.tasks to show correct text */}
            <div className="space-x-2">
              <button
                onClick={() => editTask(index)}
                className="bg-yellow-500 text-white px-2 py-1 rounded hover:bg-yellow-600"
              >
                Edit
              </button>
              <button
                onClick={() => deleteTask(t.id)}
                className="bg-red-500 text-white px-2 py-1 rounded hover:bg-red-600"
              >
                Delete
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default ToDoList;
